## Why This Is Asked
This problem tests the ability to model selections of multiple disjoint subarrays with an exact count — a common dynamic programming pattern in interviews.

## Key Concepts
- **DP on prefix**: State dp[i][t] tracks the best total using the first i elements with exactly t subarrays
- **Prefix sums**: Enable O(1) calculation of any subarray sum
- **Backpointers**: Store decisions to reconstruct the chosen subarrays
- **Edge cases**: Handle when n < k or when all values are negative

## Code Example
```javascript
function maxKSubarrays(A, k) {
  const n = A.length;
  const pref = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) pref[i] = pref[i - 1] + A[i - 1];

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const prev = Array.from({ length: n + 1 }, () => Array(k + 1).fill(null));
  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 0; t <= k; t++) {
      if (dp[i - 1][t] >= dp[i][t]) {
        dp[i][t] = dp[i - 1][t];
        prev[i][t] = { skip: true };
      }
      for (let l = 1; l <= i; l++) {
        if (t > 0 && dp[l - 1][t - 1] !== -Infinity) {
          const val = dp[l - 1][t - 1] + (pref[i] - pref[l - 1]);
          if (val > dp[i][t]) {
            dp[i][t] = val;
            prev[i][t] = { skip: false, l, t: t - 1 };
          }
        }
      }
    }
  }

  const result = [];
  let i = n, t = k;
  while (i > 0 && t > 0) {
    const p = prev[i][t];
    if (p.skip) { i--; continue; }
    result.push([p.l, i]);
    i = p.l - 1; t = p.t;
  }
  return { value: dp[n][k], subarrays: result.reverse() };
}
```

## Why This Problem Matters
This problem assesses sophisticated dynamic programming techniques by combining palindrome preprocessing, optimal substructure for non-overlapping segment selection, and explicit solution reconstruction. It integrates preprocessing with suffix-based DP while requiring careful index management.

## Key Concepts
- Palindrome table (isPal) DP preprocessing for O(1) palindrome queries
- 2D DP with optimal substructure and complete solution reconstruction
- Complexity analysis: Time O(n²k), Space O(n² + nk)

## Code Example
```javascript
function maxPalBlocks(s, k) {
  const n = s.length;
  const isPal = Array.from({length: n}, () => Array(n).fill(false));

  // Precompute palindrome table
  for (let len = 1; len <= n; len++) {
    for (let l = 0; l + len <= n; l++) {
      const r = l + len - 1;
      isPal[l][r] = (s[l] === s[r] && (len <= 2 || isPal[l+1][r-1]));
    }
  }

  // Initialize DP tables
  const dp = Array.from({length: n + 1}, () => Array(k + 1).fill(0));
  const trace = Array.from({length: n + 1}, () => Array(k + 1).fill(null));

  // Fill DP table
  for (let i = n - 1; i >= 0; i--) {
    for (let t = 1; t <= k; t++) {
      dp[i][t] = dp[i + 1][t];
      trace[i][t] = {type: 'skip'};

      for (let j = i; j < n; j++) {
        if (isPal[i][j]) {
          const val = (j - i + 1) + dp[j + 1][t - 1];
          if (val > dp[i][t]) {
            dp[i][t] = val;
            trace[i][t] = {type: 'take', l: i, r: j};
          }
        }
      }
    }
  }

  // Reconstruct solution
  const blocks = [];
  let i = 0, t = k;
  while (t > 0 && i < n) {
    const choice = trace[i][t];
    if (choice.type === 'take') {
      blocks.push([choice.l, choice.r]);
      i = choice.r + 1;
      t--;
    } else {
      i++;
    }
  }

  return {maxLength: dp[0][k], blocks};
}
```

